<?php
namespace App\Extensions\ChatbotWhatsapp\System\Services;
use App\Extensions\ChatbotWhatsapp\System\Models\OutboundMessage; use Illuminate\Support\Str;
class MessagingRuntime { public function __construct(private readonly MessagingProviderRegistry $providers){} public function send(array $payload):array{$provider=$this->providers->get($payload['provider']);$record=OutboundMessage::query()->create(['uuid'=>(string)Str::uuid(),'provider'=>$payload['provider'],'channel'=>$payload['channel']??'whatsapp','to'=>$payload['to'],'payload'=>$payload,'status'=>'sending','scheduled_at'=>$payload['scheduled_at']??null]);try{$result=isset($payload['scheduled_at'])?$provider->schedule($payload,new \DateTimeImmutable($payload['scheduled_at'])):$provider->send($payload);$record->forceFill(['status'=>$result['status']??'sent','provider_message_id'=>$result['id']??null,'provider_response'=>$result])->save();return $record->fresh()->toArray();}catch(\Throwable $e){$record->forceFill(['status'=>'failed','failure_reason'=>$e->getMessage()])->save();throw $e;}} public function retry(OutboundMessage $m):array{$p=$m->payload;$p['provider']=$m->provider;$m->increment('retry_count');return $this->send($p);} }
